describe('Video Captions Accessibility', () => {
  beforeEach(() => {
    cy.visit('/videos');
  });

  it('should display captions when video is played', () => {
    // Intercept the API call to fetch video details
    cy.intercept('GET', '/api/videos/123').as('getVideo');
    cy.wait('@getVideo');

    // Get the first video element
    cy.get('[data-testid="video-container"]').first().should('be.visible');
    cy.get('[data-testid="video-player"]').should('be.visible');

    // Verify caption button is visible
    cy.get('[data-testid="caption-toggle"]').should('be.visible');

    // Verify captions are initially hidden
    cy.get('[data-testid="video-captions"]').should('not.exist');

    // Click the caption button to toggle captions
    cy.get('[data-testid="caption-toggle"]').click();

    // Verify captions are now visible
    cy.get('[data-testid="video-captions"]').should('be.visible');

    // Verify caption text is displayed
    cy.get('[data-testid="video-captions"]').should('contain', 'Video caption text');

    // Verify caption controls are present
    cy.get('[data-testid="caption-play-pause"]').should('be.visible');
    cy.get('[data-testid="caption-volume-control"]').should('be.visible');

    // Verify caption playback controls are functional
    cy.get('[data-testid="caption-play-pause"]').click();
    cy.get('[data-testid="caption-play-pause"]').should('be.visible');

    // Verify captions are synchronized with video
    cy.get('[data-testid="video-player"]').should('be.visible');
    cy.get('[data-testid="video-player"]').should('have.attr', 'currentTime', '10');
  });

  it('should hide captions when video is paused or closed', () => {
    // Intercept the API call to fetch video details
    cy.intercept('GET', '/api/videos/123').as('getVideo');
    cy.wait('@getVideo');

    // Get the first video element
    cy.get('[data-testid="video-container"]').first().should('be.visible');

    // Verify captions are visible
    cy.get('[data-testid="video-captions"]').should('be.visible');

    // Verify caption controls are visible
    cy.get('[data-testid="caption-play-pause"]').should('be.visible');

    // Click the pause button to pause video
    cy.get('[data-testid="caption-play-pause"]').click();

    // Verify captions are still visible
    cy.get('[data-testid="video-captions"]').should('be.visible');

    // Verify captions are still synchronized with video
    cy.get('[data-testid="video-player"]').should('have.attr', 'currentTime', '10');

    // Verify captions are still visible when video is paused
    cy.get('[data-testid="caption-play-pause"]').click();
    cy.get('[data-testid="caption-play-pause"]').should('be.visible');

    // Verify captions are hidden when video is closed
    cy.get('[data-testid="video-close-button"]').click();
    cy.get('[data-testid="video-container"]').should('not.exist');
    cy.get('[data-testid="video-captions"]').should('not.exist');
  });
});
